(()=>{let s=self;s.addEventListener("push",e=>{let t="PictoLink",i="Tienes un nuevo mensaje",o="pictolink-message",l="/chat";if(e.data)try{let n=e.data.json();t=n.title??t,i=n.body??i,o=n.tag??o,l=n.url??l}catch{i=e.data.text()}e.waitUntil(s.clients.matchAll({type:"window",includeUncontrolled:!0}).then(n=>{if(!n.some(n=>!0===n.focused))return s.registration.showNotification(t,{body:i,icon:"/icon-192.png",badge:"/icon-192.png",tag:o,renotify:!0,data:{url:l}})}))}),s.addEventListener("notificationclick",e=>{e.notification.close();let t=e.notification.data?.url??"/chat";e.waitUntil(s.clients.matchAll({type:"window",includeUncontrolled:!0}).then(n=>{for(let i of n)if("focus"in i){if("navigate"in i)try{i.navigate(t)}catch{}return i.focus()}return s.clients.openWindow(t)}))})})();
